steps.code:
{%- comment -%} blocks/text.liquid {%- endcomment -%}
<div class="text" {{ block.shopify_attributes }}>
  {{ block.settings.text }}
</div>

{% schema %}
{
  "name": "Texto",
  "settings": [
    { "type": "richtext", "id": "text", "label": "Texto" },
    { "type": "text_alignment", "id": "alignment", "label": "Alinhamento" }
  ],
  "presets": [
    { "name": "Texto" }
  ]
}
{% endschema %}

{%- comment -%} sections/faixa.liquid {%- endcomment -%}
<section class="faixa">
  {% content_for "blocks" %}
</section>

{% schema %}
{
  "name": "Faixa",
  "blocks": [
    { "type": "@theme" },
    { "type": "@app" }
  ],
  "presets": [{ "name": "Faixa" }]
}
{% endschema %}

{%- comment -%} blocks/coluna.liquid {%- endcomment -%}
<div class="coluna" {{ block.shopify_attributes }}>
  {% content_for "blocks" %}
</div>

{% schema %}
{
  "name": "Coluna",
  "blocks": [{ "type": "@theme" }, { "type": "@app" }],
  "presets": [
    {
      "name": "Coluna com texto",
      "blocks": [
        { "type": "text", "settings": { "text": "<h3>Olá, mundo!</h3>" } }
      ]
    }
  ]
}
{% endschema %}

{%- comment -%} dentro de uma section ou block {%- endcomment -%}
{% content_for "block", type: "button", id: "cta-principal", color: "red" %}

{%- comment -%} blocks/button.liquid — recebe {{ color }} {%- endcomment -%}
<a class="button button--{{ color }}" href="{{ block.settings.link }}">
  {{ block.settings.label }}
</a>
